package com.fernandaazevedo.support;
import com.fernandaazevedo.common.DemoService; import com.fernandaazevedo.domain.AppUser; import jakarta.servlet.http.HttpSession; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/tickets") public class SupportController {
 private final SupportTicketRepository tickets; private final TicketMessageRepository messages; private final SupportAccessService access; private final DemoService demo;
 public SupportController(SupportTicketRepository t,TicketMessageRepository m,SupportAccessService a,DemoService d){tickets=t;messages=m;access=a;demo=d;}
 @GetMapping public ResponseEntity<?> list(HttpSession s){AppUser u=user(s);if(u==null)return unauthorized();boolean staff="ADMIN".equals(u.role)||("SUPPORT".equals(u.role)&&u.permissions.contains("support.tickets.view"));return ResponseEntity.ok(staff?tickets.findAll():tickets.findByRequesterIdOrderByUpdatedAtDesc(u.id));}
 @PostMapping public ResponseEntity<?> create(@RequestBody Map<String,Object>b,HttpSession s){AppUser u=user(s);if(u==null)return unauthorized();String subject=String.valueOf(b.getOrDefault("subject","")).strip();if(subject.isBlank()||subject.length()>300)return ResponseEntity.badRequest().body(Map.of("message","Informe um resumo de até 300 caracteres."));SupportTicket t=new SupportTicket();t.ticketNumber="FA-"+Year.now().getValue()+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(Locale.ROOT);t.requesterId=u.id;t.requesterName=u.name;t.requesterRole=u.role;t.subject=subject;t.category=String.valueOf(b.getOrDefault("category","Outro"));t.priority=String.valueOf(b.getOrDefault("priority","NORMAL"));t=tickets.save(t);demo.audit(u.email,"TICKET_CREATED",t.ticketNumber,null,t.category);return ResponseEntity.status(201).body(t);}
 @GetMapping("/{id}/messages") public ResponseEntity<?> history(@PathVariable Long id,HttpSession s){var a=access.authorize(id,uid(s),false);if(a.isEmpty())return forbidden();return ResponseEntity.ok(messages.findByTicketIdOrderByCreatedAtAsc(id).stream().filter(m->a.get().staff()||!m.internalNote).toList());}
 @PostMapping("/{id}/claim") public ResponseEntity<?> claim(@PathVariable Long id,HttpSession s){var a=access.authorize(id,uid(s),true);if(a.isEmpty()||!a.get().staff())return forbidden();var t=a.get().ticket();if(t.assignedSupportId!=null&&!t.assignedSupportId.equals(a.get().user().id))return ResponseEntity.status(409).body(Map.of("message","Ticket já assumido por outro atendente."));t.assignedSupportId=a.get().user().id;t.assignedSupportName=a.get().user().name;t.status="IN_PROGRESS";t.updatedAt=LocalDateTime.now();tickets.save(t);demo.audit(a.get().user().email,"TICKET_CLAIMED",t.ticketNumber,null,t.assignedSupportName);return ResponseEntity.ok(t);}
 @PatchMapping("/{id}/status") public ResponseEntity<?> status(@PathVariable Long id,@RequestBody Map<String,String>b,HttpSession s){var a=access.authorize(id,uid(s),true);if(a.isEmpty())return forbidden();String next=b.getOrDefault("status","");Set<String> allowed=a.get().staff()?Set.of("IN_PROGRESS","WAITING_USER","RESOLVED","CLOSED","REOPENED"):Set.of("REOPENED");if(!allowed.contains(next))return forbidden();var t=a.get().ticket();String before=t.status;t.status=next;t.updatedAt=LocalDateTime.now();if("RESOLVED".equals(next)||"CLOSED".equals(next))t.resolvedAt=LocalDateTime.now();tickets.save(t);demo.audit(a.get().user().email,"TICKET_STATUS_CHANGED",t.ticketNumber,before,next);return ResponseEntity.ok(t);}
 private Long uid(HttpSession s){return s.getAttribute("uid") instanceof Long id?id:null;} private AppUser user(HttpSession s){Long id=uid(s);return id==null?null:demo.users.findById(id).orElse(null);} private ResponseEntity<?> unauthorized(){return ResponseEntity.status(401).body(Map.of("message","Sessão expirada."));} private ResponseEntity<?> forbidden(){return ResponseEntity.status(403).body(Map.of("message","Você não tem permissão para esta ação."));}
}
